/** CI-local harness: builds only repository runtime or in-repository test fixtures.
 * Accepted hashes are immutable review baselines, never regenerated by this suite. */
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {createRequire} from 'node:module';
import {createHash} from 'node:crypto';
export const suite=path.dirname(fileURLToPath(import.meta.url));
export const host=path.resolve(suite,'../..');
export const repository=path.resolve(host,'..');
export const fixtures=path.join(suite,'fixtures');
export const canonicalSource=path.join(host,'src/case-data/reviewed-transport.json');
export const require=createRequire(path.join(host,'package.json'));
export const THREE=require('three');
const esbuild=require('esbuild');
export const pins=JSON.parse(fs.readFileSync(path.join(fixtures,'accepted-pins.json'),'utf8'));
export const hash=value=>createHash('sha256').update(value).digest('hex');
export const canonical=value=>Array.isArray(value)?'['+value.map(canonical).join(',')+']':value&&typeof value==='object'?'{'+Object.keys(value).sort().map(key=>JSON.stringify(key)+':'+canonical(value[key])).join(',')+'}':JSON.stringify(value);
export const semanticHash=value=>hash(canonical(value));
export const build=options=>esbuild.build({absWorkingDir:host,...options,nodePaths:[path.join(host,'node_modules')],logLevel:'silent'});
export function assertSourcePin(relative){
  let source=fs.readFileSync(path.join(host,'src',relative),'utf8');
  if(relative==='case-data/adapter.ts'){
    assert.match(source,/^import reviewedTransport from '\.\/runtime-transport';/);
    source=source.replace("import reviewedTransport from './runtime-transport';","import reviewedTransport from './reviewed-transport.json';");
  }
  assert.equal(hash(source),pins.runtimeSources[relative],relative);
}
export function helpers(targetName){
 const dir=path.join(host,'src',targetName),runtime=dir;
 async function load(entry){const full=path.resolve(dir,entry);assert.ok(full.startsWith(path.join(host,'src')+path.sep),'Runtime load must remain inside repository src');const result=await build({entryPoints:[full],bundle:true,write:false,format:'cjs',platform:'node',external:['three','maplibre-gl']});const mod={exports:{}};new Function('require','module','exports',result.outputFiles[0].text)(require,mod,mod.exports);return mod.exports;}
 async function renderModule(){const contents=targetName==='case-scene'?`import React from 'react';import{renderToStaticMarkup}from'react-dom/server';import{CaseSceneEvidence}from'./CaseSceneEvidence';import{CaseEvidenceDetails}from'../case-data/CaseDiagramPanel';export const render=(caseFile,model,state)=>renderToStaticMarkup(<CaseSceneEvidence caseFile={caseFile} model={model} state={state} onAction={()=>{}}/>);export const evidence=(caseFile,claimId)=>renderToStaticMarkup(<CaseEvidenceDetails caseFile={caseFile} claimId={claimId}/>);`:`import React from 'react';import{renderToStaticMarkup}from'react-dom/server';import{CaseDiagramPanel,CaseEvidenceDetails}from'./CaseDiagramPanel';export function render(caseFile,view='diagram'){return renderToStaticMarkup(<CaseDiagramPanel caseFile={caseFile} initialView={view}/>);}export function renderEvidence(caseFile,claimId){return renderToStaticMarkup(<CaseEvidenceDetails caseFile={caseFile} claimId={claimId}/>);}`;
 const result=await build({stdin:{contents,resolveDir:runtime,loader:'tsx'},bundle:true,write:false,format:'cjs',platform:'node',jsx:'automatic',loader:{'.css':'empty'}});const mod={exports:{}};new Function('require','module','exports',result.outputFiles[0].text)(require,mod,mod.exports);return mod.exports;}
 return {dir,runtime,load,renderModule};
}
export async function acceptedCatalog(){
 const raw=fs.readFileSync(canonicalSource);
 assert.equal(raw.byteLength,pins.originalRawBytes);assert.equal(hash(raw),pins.originalRawSha256);
 const {expandTransport}=await helpers('case-data').load('expand-transport.ts');
 const catalog=expandTransport(JSON.parse(raw));
 assert.equal(semanticHash(catalog),pins.expandedCatalogSha256,'Independent accepted expanded catalog hash');
 return catalog;
}
